components.css:
.ds-process-pipeline{font-family:Manrope,Arial,sans-serif;color:var(--ink,#f3f0e8);background:var(--canvas,#060706)}
.ds-principles li{box-sizing:border-box}
.ds-process-pipeline{position:relative;height:650px;--pipeline-progress:1}
.ds-pipeline-track{position:absolute;inset:0;pointer-events:none}
.ds-pipeline-svg{width:100%;height:100%;overflow:visible;fill:none}
.ds-pipeline-desktop{display:none}
.ds-pipeline-shell,.ds-pipeline-core,.ds-pipeline-fill{stroke-linecap:round;stroke-linejoin:round;vector-effect:non-scaling-stroke}
.ds-pipeline-shell{stroke:var(--line,#33372f);stroke-width:14px}
.ds-pipeline-core{stroke:var(--canvas,#060706);stroke-width:8px}
.ds-pipeline-fill{stroke:var(--accent,#ff5a1f);stroke-width:4px;stroke-dasharray:1;stroke-dashoffset:calc(1 - var(--pipeline-progress))}
.ds-pipeline-packet{fill:var(--ink,#f3f0e8);stroke:var(--accent,#ff5a1f);stroke-width:2px;visibility:hidden}
.ds-principles{position:absolute;inset:0;list-style:none;counter-reset:principle;margin:0;padding:0}
.ds-principles li{counter-increment:principle;position:absolute;left:28.125%;top:10.77%;transform:translate(-50%,-50%);width:144px;min-height:84px;display:flex;flex-direction:column;justify-content:center;gap:12px;padding:16px;background:var(--canvas,#060706);border:1px solid var(--line,#33372f);border-radius:12px;transition:border-color .2s}
.ds-principles li:nth-child(2){left:71.875%;top:30.77%}
.ds-principles li:nth-child(3){top:50.77%}
.ds-principles li:nth-child(4){left:71.875%;top:70.77%}
.ds-principles li:nth-child(5){top:90.77%}
.ds-principles li::before{content:counter(principle,decimal-leading-zero);position:absolute;right:14px;top:14px;font-size:12px;line-height:1;font-variant-numeric:tabular-nums;color:var(--secondary,#b6b8ae)}
.ds-principles .ds-pipeline-step-icon{width:24px;height:24px;color:var(--accent,#ff5a1f)}
.ds-principles h3{font-size:16px;line-height:1.5;margin:0}
.ds-principles li.ds-is-reached{border-color:var(--accent,#ff5a1f)}
.ds-pipeline-animated .ds-principles li:not(.ds-is-reached) .ds-pipeline-step-icon{color:var(--secondary,#b6b8ae)}
@media(min-width:960px){
  .ds-process-pipeline{height:280px}
  .ds-pipeline-mobile{display:none}
  .ds-pipeline-desktop{display:block}
  .ds-process-pipeline .ds-principles li{left:10%;top:28.571%;width:16%;max-width:180px}
  .ds-process-pipeline .ds-principles li:nth-child(2){left:30%;top:71.429%}
  .ds-process-pipeline .ds-principles li:nth-child(3){left:50%}
  .ds-process-pipeline .ds-principles li:nth-child(4){left:70%;top:71.429%}
  .ds-process-pipeline .ds-principles li:nth-child(5){left:90%}
}

@media(prefers-reduced-motion:reduce){.ds-principles li{transition:none}}
